

        /* =====================================================
           VARIABLES
        ===================================================== */

        :root {
            --orange: #ff6b35;
            --orange-light: #ff914d;
            --gold: #ffd166;
            --dark: #070707;
            --dark-2: #101010;
            --dark-3: #171717;
            --gray: #a7a7a7;
            --white: #ffffff;
            --border: rgba(255,255,255,0.08);
            --glass: rgba(255,255,255,0.05);
            --shadow: 0 20px 60px rgba(0,0,0,.4);
        }

        /* =====================================================
           RESET
        ===================================================== */

        * {
            margin: 0;
            padding: 0;
            box-sizing: border-box;
            scroll-behavior: smooth;
        }

        body {
            font-family: 'Montserrat', sans-serif;
            background: var(--dark);
            color: var(--white);
            overflow-x: hidden;
        }

        a {
            text-decoration: none;
            color: inherit;
        }

        img {
            max-width: 100%;
            display: block;
        }

        button {
            font-family: inherit;
        }

        /* =====================================================
           SCROLLBAR
        ===================================================== */

        ::-webkit-scrollbar {
            width: 8px;
        }

        ::-webkit-scrollbar-track {
            background: #050505;
        }

        ::-webkit-scrollbar-thumb {
            background: linear-gradient(var(--orange), var(--gold));
            border-radius: 20px;
        }

        /* =====================================================
           ACCESSIBILITÉ — LIEN D'ÉVITEMENT
        ===================================================== */

        .skip-link {
            position: absolute;
            top: -60px;
            left: 10px;
            z-index: 3000;

            padding: 12px 20px;
            border-radius: 10px;

            background: var(--orange);
            color: white;
            font-weight: 700;

            transition: top .3s;
        }

        .skip-link:focus {
            top: 10px;
        }

        /* =====================================================
           NAVBAR
        ===================================================== */

        .navbar {
            position: fixed;
            top: 0;
            left: 0;
            width: 100%;
            z-index: 1000;

            display: flex;
            align-items: center;
            justify-content: space-between;

            padding: 18px 7%;

            background: rgba(5,5,5,.65);
            backdrop-filter: blur(18px);
            border-bottom: 1px solid transparent;

            transition: .4s;
        }

        .navbar.scrolled {
            background: rgba(7,7,7,.95);
            border-bottom-color: var(--border);
            padding-top: 14px;
            padding-bottom: 14px;
        }

        .logo {
            display: flex;
            align-items: center;
            gap: 12px;
            font-weight: 800;
            font-size: 1.15rem;
            letter-spacing: 1px;
        }

        .logo-icon {
            width: 42px;
            height: 42px;
            display: grid;
            place-items: center;

            border-radius: 50%;
            background: linear-gradient(135deg,var(--orange),var(--gold));

            color: #111;
            font-size: 20px;

            box-shadow: 0 0 25px rgba(255,107,53,.3);
        }

        .logo span {
            color: var(--gold);
        }

        .nav-links {
            display: flex;
            align-items: center;
            gap: 32px;
            list-style: none;
        }

        .nav-links a {
            position: relative;
            color: #ddd;
            font-size: .9rem;
            font-weight: 600;
            transition: .3s;
        }

        .nav-links a::after {
            content: "";
            position: absolute;
            left: 0;
            bottom: -8px;
            width: 0;
            height: 2px;
            background: var(--orange);
            transition: .3s;
        }

        .nav-links a:hover,
        .nav-links a.active {
            color: var(--gold);
        }

        .nav-links a:hover::after,
        .nav-links a.active::after {
            width: 100%;
        }

        .menu-toggle {
            display: none;
            background: none;
            border: none;
            color: white;
            font-size: 28px;
            cursor: pointer;
        }

        /* =====================================================
           HERO
        ===================================================== */

        .hero {
            min-height: 100vh;
            position: relative;

            display: flex;
            align-items: center;
            justify-content: center;

            text-align: center;
            padding: 120px 20px 60px;

            background:
                linear-gradient(
                    180deg,
                    rgba(0,0,0,.35),
                    rgba(0,0,0,.88)
                ),
                url("data:image/jpeg;base64,")
                center/cover no-repeat;

            overflow: hidden;
        }

        .hero::before {
            content: "";
            position: absolute;
            width: 600px;
            height: 600px;

            background: var(--orange);
            opacity: .08;

            filter: blur(120px);
            border-radius: 50%;
        }

        .hero-content {
            position: relative;
            max-width: 900px;
            z-index: 2;
        }

        .hero-badge {
            display: inline-flex;
            align-items: center;
            gap: 8px;

            padding: 9px 18px;
            margin-bottom: 25px;

            border: 1px solid rgba(255,209,102,.3);
            background: rgba(255,209,102,.08);

            border-radius: 50px;

            color: var(--gold);
            font-size: .8rem;
            font-weight: 600;
            text-transform: uppercase;
            letter-spacing: 2px;
        }

        .hero h1 {
            font-family: 'Playfair Display', serif;
            font-size: clamp(3rem, 7vw, 6.5rem);
            line-height: 1;
            margin-bottom: 25px;

            background: linear-gradient(
                120deg,
                #fff,
                var(--gold),
                var(--orange)
            );

            -webkit-background-clip: text;
            -webkit-text-fill-color: transparent;
        }

        .hero p {
            max-width: 720px;
            margin: auto;

            color: #ddd;
            line-height: 1.8;
            font-size: 1.05rem;
        }

        .hero-buttons {
            margin-top: 35px;

            display: flex;
            justify-content: center;
            flex-wrap: wrap;
            gap: 12px;
        }

        .btn {
            display: inline-flex;
            align-items: center;
            justify-content: center;
            gap: 10px;

            padding: 14px 25px;

            border-radius: 50px;
            border: none;

            background: linear-gradient(
                135deg,
                var(--orange),
                var(--orange-light)
            );

            color: white;
            font-weight: 700;
            cursor: pointer;

            transition: .35s;
            box-shadow: 0 10px 30px rgba(255,107,53,.2);
        }

        .btn:hover {
            transform: translateY(-4px);
            box-shadow: 0 15px 40px rgba(255,107,53,.4);
        }

        .btn-outline {
            background: rgba(255,255,255,.04);
            border: 1px solid rgba(255,107,53,.6);
            box-shadow: none;
        }

        /* =====================================================
           SECTION
        ===================================================== */

        section {
            padding: 110px 7%;
        }

        .section-header {
            max-width: 750px;
            margin: 0 auto 60px;
            text-align: center;
        }

        .section-tag {
            display: inline-block;
            color: var(--orange);
            font-size: .75rem;
            font-weight: 800;
            letter-spacing: 3px;
            text-transform: uppercase;
            margin-bottom: 12px;
        }

        .section-title {
            font-family: 'Playfair Display', serif;
            font-size: clamp(2.2rem, 5vw, 3.7rem);
            margin-bottom: 18px;
        }

        .section-description {
            color: var(--gray);
            line-height: 1.8;
        }

        /* =====================================================
           STATS
        ===================================================== */

        .stats {
            margin-top: -50px;
            position: relative;
            z-index: 10;

            display: grid;
            grid-template-columns: repeat(4,1fr);
            gap: 18px;

            padding: 0 7%;
        }

        .stat {
            padding: 28px 20px;
            text-align: center;

            background: rgba(22,22,22,.9);
            border: 1px solid var(--border);

            border-radius: 18px;
            backdrop-filter: blur(15px);

            transition: .3s;
        }

        .stat:hover {
            transform: translateY(-7px);
            border-color: rgba(255,107,53,.5);
        }

        .stat strong {
            display: block;
            font-size: 2rem;
            color: var(--gold);
            margin-bottom: 5px;
        }

        .stat span {
            color: var(--gray);
            font-size: .8rem;
        }

        /* =====================================================
           HISTOIRE
        ===================================================== */

        .history {
            background:
                radial-gradient(
                    circle at 10% 20%,
                    rgba(255,107,53,.07),
                    transparent 35%
                ),
                var(--dark);
        }

        .history-wrapper {
            max-width: 1100px;
            margin: auto;

            display: grid;
            grid-template-columns: .8fr 1.2fr;
            gap: 70px;
            align-items: center;
        }

        .history-image {
            position: relative;
        }

        .history-image img {
            width: 100%;
            height: 520px;
            object-fit: cover;

            border-radius: 25px;
            filter: saturate(.8);
        }

        .history-image::after {
            content: none;
        }

        .history-text h3 {
            font-family: 'Playfair Display', serif;
            font-size: 2rem;
            color: var(--gold);
            margin-bottom: 25px;
        }

        .history-text h3:not(:first-child) {
            margin-top: 10px;
        }

        .history-text p {
            color: #ccc;
            line-height: 1.9;
            margin-bottom: 18px;
        }

        .highlight {
            padding: 20px;

            border-left: 3px solid var(--orange);
            background: rgba(255,107,53,.05);

            border-radius: 0 12px 12px 0;

            margin: 25px 0;
        }

        .highlight strong {
            color: var(--gold);
        }

        /* =====================================================
           VOIR PLUS / VOIR MOINS
        ===================================================== */

        .more-content {
            display: grid;
            grid-template-rows: 0fr;
            opacity: 0;
            transition: grid-template-rows .5s ease, opacity .4s ease;
        }

        .more-content > div {
            overflow: hidden;
        }

        .more-content.show {
            display: grid;
            grid-template-rows: 1fr;
            opacity: 1;
        }

        .toggle-btn {
            width: max-content;

            background: none;
            border: none;

            color: var(--orange);
            font-weight: 800;
            cursor: pointer;
            font-size: .95rem;

            display: flex;
            align-items: center;
            gap: 8px;

            margin: 4px 0 28px;
            transition: .3s;
        }

        .toggle-btn:hover {
            color: var(--gold);
            gap: 14px;
        }

        .toggle-btn .icon {
            display: inline-block;
            transition: transform .3s;
        }

        .toggle-btn.open .icon {
            transform: rotate(90deg);
        }

        /* =====================================================
           INITIATIVES / VIE COMMUNAUTAIRE
        ===================================================== */

        .initiatives {
            background:
                radial-gradient(
                    circle at 90% 10%,
                    rgba(255,209,102,.06),
                    transparent 40%
                ),
                var(--dark-2);
        }

        .initiative-card {
            max-width: 900px;
            margin: auto;

            padding: 45px;

            background:
                linear-gradient(
                    145deg,
                    rgba(255,255,255,.05),
                    rgba(255,255,255,.015)
                );

            border: 1px solid var(--border);
            border-radius: 25px;
        }

        .initiative-card h3 {
            font-family: 'Playfair Display', serif;
            font-size: 2rem;
            color: var(--gold);
            margin-bottom: 6px;
        }

        .initiative-subtitle {
            display: block;

            color: var(--orange);
            font-size: .78rem;
            font-weight: 800;
            text-transform: uppercase;
            letter-spacing: 2px;

            margin-bottom: 22px;
        }

        .initiative-card p {
            color: #ccc;
            line-height: 1.9;
            margin-bottom: 18px;
        }

        .initiative-card .highlight {
            margin-top: 25px;
        }

        .initiative-card .highlight p {
            margin-bottom: 0;
            margin-top: 8px;
        }

        /* =====================================================
           LIEUX
        ===================================================== */

        .places {
            background: var(--dark-2);
        }

        .places-grid {
            max-width: 1250px;
            margin: auto;

            display: grid;
            grid-template-columns: repeat(2,1fr);
            gap: 25px;
        }

        .place-card {
            position: relative;
            min-height: 400px;

            overflow: hidden;
            border-radius: 25px;

            border: 1px solid var(--border);

            background: #111;

            transition: .5s;
        }

        .place-card:hover {
            transform: translateY(-10px);
            border-color: rgba(255,107,53,.6);
            box-shadow: var(--shadow);
        }

        .place-card img {
            width: 100%;
            height: 100%;
            min-height: 400px;

            object-fit: cover;

            transition: .7s;
        }

        .place-card:hover img {
            transform: scale(1.08);
        }

        .place-overlay {
            position: absolute;
            inset: 0;

            display: flex;
            flex-direction: column;
            justify-content: flex-end;

            padding: 30px;

            background:
                linear-gradient(
                    transparent 20%,
                    rgba(0,0,0,.95)
                );
        }

        .place-number {
            position: absolute;
            top: 22px;
            right: 22px;

            width: 45px;
            height: 45px;

            display: grid;
            place-items: center;

            border-radius: 50%;

            background: rgba(0,0,0,.6);
            border: 1px solid rgba(255,255,255,.2);

            color: var(--gold);
            font-weight: 800;
        }

        .place-overlay h3 {
            font-family: 'Playfair Display', serif;
            font-size: 1.8rem;
            margin-bottom: 10px;
        }

        .place-overlay p {
            color: #ccc;
            line-height: 1.6;
            margin-bottom: 18px;
        }

        .read-more {
            width: max-content;

            background: none;
            border: none;

            color: var(--orange);
            font-weight: 800;
            cursor: pointer;

            display: flex;
            align-items: center;
            gap: 8px;

            transition: .3s;
        }

        .read-more:hover {
            color: var(--gold);
            gap: 14px;
        }

        /* =====================================================
           CULTURE
        ===================================================== */

        .culture {
            position: relative;
            overflow: hidden;

            background:
                linear-gradient(
                    135deg,
                    rgba(255,107,53,.12),
                    transparent
                ),
                var(--dark);
        }

        .culture-content {
            max-width: 1000px;
            margin: auto;
            text-align: center;
        }

        .culture-icon {
            width: 80px;
            height: 80px;

            display: grid;
            place-items: center;

            margin: 0 auto 25px;

            border-radius: 50%;

            background: linear-gradient(
                135deg,
                var(--orange),
                var(--gold)
            );

            color: #111;
            font-size: 35px;
        }

        .culture-content p {
            max-width: 800px;
            margin: auto;

            color: #ccc;
            line-height: 1.9;
        }

        /* =====================================================
           GALERIE
        ===================================================== */

        .gallery {
            background: var(--dark-2);
        }

        .gallery-grid {
            max-width: 1250px;
            margin: auto;

            display: grid;
            grid-template-columns: repeat(3,1fr);
            gap: 18px;
        }

        .gallery-item {
            position: relative;
            aspect-ratio: 1 / 1;

            overflow: hidden;
            border-radius: 20px;

            border: 1px solid var(--border);
            cursor: pointer;

            background: #111;
        }

        .gallery-item img {
            width: 100%;
            height: 100%;
            object-fit: cover;

            transition: .6s;
        }

        .gallery-item:hover img {
            transform: scale(1.12);
        }

        .gallery-item::after {
            content: "✦ Agrandir";
            position: absolute;
            inset: auto 0 0 0;

            padding: 14px;

            background: linear-gradient(transparent, rgba(0,0,0,.85));

            color: var(--gold);
            font-size: .8rem;
            font-weight: 700;
            text-align: center;

            opacity: 0;
            transform: translateY(10px);
            transition: .3s;
        }

        .gallery-item:hover::after {
            opacity: 1;
            transform: translateY(0);
        }

        .lightbox-content {
            max-width: 900px;
            padding: 20px;
            background: #0a0a0a;
        }

        .lightbox-content img {
            width: 100%;
            border-radius: 15px;
        }

        @media(max-width:1000px) {
            .gallery-grid {
                grid-template-columns: repeat(2,1fr);
            }
        }

        @media(max-width:600px) {
            .gallery-grid {
                grid-template-columns: 1fr;
            }
        }

        /* =====================================================
           EQUIPE
        ===================================================== */

        .team-section {
            background: var(--dark-2);
        }

        .team {
            max-width: 1100px;
            margin: auto;

            display: grid;
            grid-template-columns: repeat(4,1fr);
            gap: 20px;
        }

        .member {
            text-align: center;

            padding: 30px 20px;

            background:
                linear-gradient(
                    145deg,
                    rgba(255,255,255,.06),
                    rgba(255,255,255,.015)
                );

            border: 1px solid var(--border);
            border-radius: 22px;

            transition: .4s;
        }

        .member:hover {
            transform: translateY(-10px);
            border-color: var(--orange);
        }

        .member-image {
            width: 120px;
            height: 120px;

            margin: 0 auto 20px;

            border-radius: 50%;

            padding: 4px;

            background: linear-gradient(
                135deg,
                var(--orange),
                var(--gold)
            );
        }

        .member-image img {
            width: 100%;
            height: 100%;
            object-fit: cover;

            border-radius: 50%;
            border: 4px solid #171717;
        }

        .member h4 {
            font-size: 1.1rem;
            margin-bottom: 7px;
        }

        .member p {
            color: var(--orange);
            font-size: .8rem;
            font-weight: 600;
        }

        /* =====================================================
           COMMENT VENIR
        ===================================================== */

        .venir {
            background: var(--dark);
        }

        .venir-wrapper {
            max-width: 1100px;
            margin: auto;

            display: grid;
            grid-template-columns: 1fr 1fr;
            gap: 50px;
            align-items: start;
        }

        .venir-text h3 {
            font-family: 'Playfair Display', serif;
            color: var(--gold);
            font-size: 1.5rem;
            margin-bottom: 15px;
        }

        .venir-text p {
            color: #ccc;
            line-height: 1.9;
            margin-bottom: 18px;
        }

        .venir-contact {
            margin-top: 10px;
            padding: 20px;

            border-left: 3px solid var(--orange);
            background: rgba(255,107,53,.05);
            border-radius: 0 12px 12px 0;
        }

        .venir-contact strong {
            display: block;
            color: var(--gold);
            margin-bottom: 6px;
        }

        .venir-map iframe {
            width: 100%;
            height: 420px;
            border: 1px solid var(--border);
            border-radius: 20px;
        }

        .venir-map a {
            display: inline-block;
            margin-top: 12px;
            color: var(--orange);
            font-weight: 700;
            font-size: .9rem;
        }

        .venir-map a:hover {
            color: var(--gold);
        }

        @media(max-width:1000px) {
            .venir-wrapper {
                grid-template-columns: 1fr;
            }
        }

        /* =====================================================
           FOOTER
        ===================================================== */

        footer {
            padding: 50px 7% 30px;

            text-align: center;

            background: #050505;
            border-top: 1px solid var(--border);
        }

        .footer-logo {
            font-family: 'Playfair Display', serif;
            color: var(--gold);
            font-size: 1.8rem;
            margin-bottom: 12px;
        }

        footer p {
            color: var(--gray);
            font-size: .85rem;
        }

        .footer-line {
            width: 80px;
            height: 2px;

            background: linear-gradient(
                90deg,
                var(--orange),
                var(--gold)
            );

            margin: 20px auto;
        }

        /* =====================================================
           MODAL
        ===================================================== */

        .modal {
            position: fixed;
            inset: 0;

            display: none;
            align-items: center;
            justify-content: center;

            padding: 25px;

            background: rgba(0,0,0,.85);
            backdrop-filter: blur(10px);

            z-index: 2000;
        }

        .modal.show {
            display: flex;
        }

        .modal-content {
            position: relative;

            width: 100%;
            max-width: 700px;

            max-height: 85vh;
            overflow-y: auto;

            padding: 40px;

            border-radius: 25px;

            background:
                linear-gradient(
                    145deg,
                    #1d1d1d,
                    #0e0e0e
                );

            border: 1px solid rgba(255,107,53,.5);

            box-shadow: 0 30px 100px rgba(0,0,0,.7);

            animation: modalIn .35s ease;
        }

        @keyframes modalIn {
            from {
                opacity: 0;
                transform: translateY(30px) scale(.96);
            }

            to {
                opacity: 1;
                transform: translateY(0) scale(1);
            }
        }

        .modal-content h2 {
            font-family: 'Playfair Display', serif;
            color: var(--gold);
            font-size: 2rem;
            margin-bottom: 20px;
        }

        .modal-content h2:not(:first-child) {
            margin-top: 30px;
        }

        .modal-content p {
            color: #ccc;
            line-height: 1.9;
            margin-bottom: 14px;
        }

        .modal-content strong {
            color: var(--gold);
            display: block;
            margin-top: 18px;
            margin-bottom: 6px;
        }

        .close {
            position: absolute;
            top: 18px;
            right: 22px;

            width: 40px;
            height: 40px;

            display: grid;
            place-items: center;

            border-radius: 50%;

            background: rgba(255,255,255,.06);
            border: 1px solid var(--border);

            color: var(--orange);
            font-size: 25px;

            cursor: pointer;
            transition: .3s;
        }

        .close:hover {
            background: var(--orange);
            color: white;
        }

        /* =====================================================
           BACK TO TOP
        ===================================================== */

        .back-top {
            position: fixed;
            right: 25px;
            bottom: 25px;

            width: 48px;
            height: 48px;

            display: grid;
            place-items: center;

            border: none;
            border-radius: 50%;

            background: var(--orange);
            color: white;

            cursor: pointer;

            opacity: 0;
            visibility: hidden;

            transition: .3s;

            z-index: 500;
        }

        .back-top.show {
            opacity: 1;
            visibility: visible;
        }

        /* =====================================================
           ANIMATIONS
        ===================================================== */

        .reveal {
            opacity: 0;
            transform: translateY(40px);
            transition: 1s ease;
        }

        .reveal.visible {
            opacity: 1;
            transform: translateY(0);
        }

        /* =====================================================
           RESPONSIVE
        ===================================================== */

        @media(max-width:1000px) {

            .stats {
                grid-template-columns: repeat(2,1fr);
            }

            .history-wrapper {
                grid-template-columns: 1fr;
            }

            .history-image {
                max-width: 600px;
                margin: auto;
            }

            .team {
                grid-template-columns: repeat(2,1fr);
            }
        }

        @media(max-width:768px) {

            .navbar {
                padding: 15px 5%;
            }

            .menu-toggle {
                display: block;
            }

            .nav-links {
                position: absolute;

                top: 100%;
                left: 0;
                width: 100%;

                display: none;
                flex-direction: column;
                align-items: flex-start;

                padding: 25px;

                background: rgba(7,7,7,.98);
                border-bottom: 1px solid var(--border);
            }

            .nav-links.open {
                display: flex;
            }

            .hero {
                min-height: 95vh;
            }

            section {
                padding: 80px 5%;
            }

            .stats {
                padding: 0 5%;
                margin-top: -30px;
            }

            .places-grid {
                grid-template-columns: 1fr;
            }

            .place-card,
            .place-card img {
                min-height: 350px;
            }

            .team {
                grid-template-columns: 1fr;
            }

            .history-image img {
                height: 400px;
            }
        }

        @media(max-width:500px) {

            .stats {
                grid-template-columns: 1fr 1fr;
            }

            .stat {
                padding: 20px 10px;
            }

            .stat strong {
                font-size: 1.5rem;
            }

            .hero-buttons {
                flex-direction: column;
            }

            .hero-buttons .btn {
                width: 100%;
            }

            .modal-content {
                padding: 30px 22px;
            }
        }

